def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Each monochrome rectangle is an object; colored specks are removed and
    # missing background cells inside an almost-complete object are restored.
    out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c))
        for y,x in q:
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
              seen.add((yy,xx)); q.append((yy,xx))
        ys=[y for y,x in q]; xs=[x for y,x in q]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        area=(y1-y0+1)*(x1-x0+1)
        if len(q)>=4 and len(q)/area>=0.75:
          for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=v
        elif len(q)<=2:
          for y,x in q: out[y][x]=bg
    # Remove isolated contaminant cells embedded in rectangle interiors by
    # replacing them with the value of their surrounding 4-neighbors.
    for r in range(1,h-1):
      for c in range(1,w-1):
        vals=[out[r-1][c],out[r+1][c],out[r][c-1],out[r][c+1]]
        if vals[0]==vals[1]==vals[2]==vals[3] and out[r][c]!=vals[0]: out[r][c]=vals[0]
    return out

