def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Remove single-cell noise (0/9) and repair holes in rectangular color blocks.
    for r in range(h):
        for c in range(w):
            if out[r][c] in (0, 9):
                out[r][c] = bg
    from collections import Counter
    seen=set()
    for r in range(h):
      for c in range(w):
        v=out[r][c]
        if v==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c))
        for y,x in q:
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and out[yy][xx]==v:
              seen.add((yy,xx)); q.append((yy,xx))
        ys=[y for y,x in q]; xs=[x for y,x in q]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        if len(q)>=4 and len(q)/((y1-y0+1)*(x1-x0+1))>=0.75:
          for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=v
    return out
